const setWorkflowStepReviewRun = `-- name: SetWorkflowStepReviewRun :execrows
UPDATE workflow_steps
SET review_run_id = ?1, updated_at = ?2
WHERE id = ?3
`

type SetWorkflowStepReviewRunParams struct {
	ReviewRunID sql.NullString
	UpdatedAt   time.Time
	ID          string
}

// Checkpoint 8D: workflow_steps.review_run_id now means "the current/most-
// recent review_run for this step" (mutable across review cycles), not
// write-once as Checkpoint 8C originally modeled it. Unconditional update, no
// WHERE review_run_id IS NULL guard: the primary anti-duplication guard
// against creating two review_runs for the same cycle is the outbox
// idempotency key (cycle-specific), not this column. Supersedes 8C's
// write-once UpdateWorkflowStepReviewRun, which 8D's cycling dispatch flow
// fully replaces (its one call site now uses this instead).
func (q *Queries) SetWorkflowStepReviewRun(ctx context.Context, arg SetWorkflowStepReviewRunParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, setWorkflowStepReviewRun, arg.ReviewRunID, arg.UpdatedAt, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const updateWorkflowAttemptOutcome = `-- name: UpdateWorkflowAttemptOutcome :execrows
UPDATE workflow_attempts
SET finished_at = ?1,
    outcome = ?2,
    error_class = ?3
WHERE id = ?4
`

type UpdateWorkflowAttemptOutcomeParams struct {
	FinishedAt sql.NullTime
	Outcome    *domain.WorkflowAttemptOutcome
	ErrorClass *domain.WorkflowErrorClass
	ID         string
}

// Updates an existing attempt row's terminal facts. Used both when a dispatch
// attempt concludes (success/failure) and when a later fact-based observation
// refines an already-recorded attempt's error_class (e.g. to
// ambiguous_worker_state) without creating a second attempt row for the same
// execution.
func (q *Queries) UpdateWorkflowAttemptOutcome(ctx context.Context, arg UpdateWorkflowAttemptOutcomeParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateWorkflowAttemptOutcome,
		arg.FinishedAt,
		arg.Outcome,
		arg.ErrorClass,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const updateWorkflowOutboxStatus = `-- name: UpdateWorkflowOutboxStatus :execrows
UPDATE workflow_outbox
SET status = ?1,
    dispatched_at = ?2,
    acknowledged_at = ?3,
    failed_at = ?4,
    error_class = ?5
WHERE id = ?6 AND status = ?7
`

type UpdateWorkflowOutboxStatusParams struct {
	Status         domain.WorkflowOutboxStatus
	DispatchedAt   sql.NullTime
	AcknowledgedAt sql.NullTime
	FailedAt       sql.NullTime
	ErrorClass     string
	ID             string
	ExpectedStatus domain.WorkflowOutboxStatus
}

// Compare-and-swap outbox status transition (pending -> dispatched ->
// acknowledged, or -> failed from either pending or dispatched). Timestamps
// are set by the caller only for the column matching the target status; the
// store layer null-guards the other two.
func (q *Queries) UpdateWorkflowOutboxStatus(ctx context.Context, arg UpdateWorkflowOutboxStatusParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateWorkflowOutboxStatus,
		arg.Status,
		arg.DispatchedAt,
		arg.AcknowledgedAt,
		arg.FailedAt,
		arg.ErrorClass,
		arg.ID,
		arg.ExpectedStatus,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const updateWorkflowRunPolicySnapshot = `-- name: UpdateWorkflowRunPolicySnapshot :execrows
UPDATE workflow_runs
SET policy_snapshot = ?1, updated_at = ?2
WHERE id = ?3
`

type UpdateWorkflowRunPolicySnapshotParams struct {
	PolicySnapshot string
	UpdatedAt      time.Time
	ID             string
}

// Checkpoint 8P-C: writes the run's policy_snapshot exactly once, right
// after creation, to embed the workflow owner's execution policy (their
// ProviderProfile priority order at that moment) -- never touched again
// afterwards, so a later Settings edit cannot reroute an in-flight run.
func (q *Queries) UpdateWorkflowRunPolicySnapshot(ctx context.Context, arg UpdateWorkflowRunPolicySnapshotParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateWorkflowRunPolicySnapshot, arg.PolicySnapshot, arg.UpdatedAt, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

